const e=[{categoria:"Esperanza",text:"Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.",reference:"Jeremías 29:11",theme:"sky"},{categoria:"Fe",text:"Es, pues, la fe la certeza de lo que se espera, la convicción de lo que no se ve.",reference:"Hebreos 11:1",theme:"violet"},{categoria:"Amor",text:"En esto hemos conocido el amor, en que él puso su vida por nosotros; también nosotros debemos poner nuestras vidas por los hermanos.",reference:"1 Juan 3:16",theme:"rose"},{categoria:"Paz",text:"La paz os dejo, mi paz os doy; yo no os la doy como el mundo la da.",reference:"Juan 14:27",theme:"emerald"},{categoria:"Fortaleza",text:"Todo lo puedo en Cristo que me fortalece.",reference:"Filipenses 4:13",theme:"amber"},{categoria:"Perdón",text:"Si confesamos nuestros pecados, él es fiel y justo para perdonar nuestros pecados, y limpiarnos de toda maldad.",reference:"1 Juan 1:9",theme:"sky"},{categoria:"Identidad",text:"Antes que te formase en el vientre te conocí, y antes que nacieses te santifiqué.",reference:"Jeremías 1:5",theme:"violet"},{categoria:"Sabiduría",text:"Fíate de Jehová de todo tu corazón, y no te apoyes en tu propia prudencia.",reference:"Proverbios 3:5",theme:"amber"},{categoria:"Salvación",text:"Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.",reference:"Juan 3:16",theme:"rose"},{categoria:"Oración",text:"Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias.",reference:"Filipenses 4:6",theme:"emerald"},{categoria:"Guía",text:"Lámpara es a mis pies tu palabra, y lumbrera a mi camino.",reference:"Salmos 119:105",theme:"sky"},{categoria:"Descanso",text:"Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar.",reference:"Mateo 11:28",theme:"violet"}];export{e as v};
